void status_req_sens_temp(void * arg)
{
	UInt8 data[2]  = {SET_SENS_TEMP, 0xFF};

#ifdef PLATFORM_933
	temperature_update();	
  os_tsk_wait(100); // wait for answer
	
 	data[1] = 	get_temp_sensor_value();
#endif
	
  d2d_tx_frame (&data[0] , sizeof_array(data)) ; 
}

